"use client";

import type { ChartRoot } from "./chart-utils";
import { useMergedRef } from "../lib/form";
import { useCallback, useDeferredValue, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import { useShortcutPlatform } from "../kbd/kbd";
import { animate, cancelFrame, frame, motion, useMotionValue } from "motion/react";

import { cn } from "../lib/cn";
import { duration, ease } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ChartAnnouncer, ChartEmpty } from "./chart-parts";
import { useInputSource } from "./chart-fit";
import { useDarkScheme } from "./flow-utils";
import {
  chartFocusClass,
  clamp,
  linear,
  niceTicks,
  slotColor,
  useElementWidth,
  resolveInstructions,
} from "./chart-utils";
import { defaultCompact, useEntrance } from "./heatmap";
import { markGlow, solidOverlayClass, useDeferredDraw, useStaggerEntrance } from "./category-bar";
import { ChartFigure } from "./chart-figure";

import {
  defaultCandlestickChartLabels,
  type CandlestickChartProps,
  parseCandles,
  type Parsed,
  MIN_SPAN,
  PILL_H,
  UP,
  DOWN,
  AXIS_CH,
} from "./candlestick-chart/model";
import { useWheelZoom, type LiveView } from "./candlestick-chart/wheel";
import { useCandleInteraction } from "./candlestick-chart/interaction";
import { priceRange, useCandleFormats } from "./candlestick-chart/derive";
import { CandleReadout } from "./candlestick-chart/readout";
import { Crosshair } from "./candlestick-chart/crosshair";
import { paintDisplay } from "./candlestick-chart/display";
import { candleShape, volumeBarShape } from "./candlestick-chart/shapes";

export {
  type Candle,
  type CandlestickChartLabels,
  defaultCandlestickChartLabels,
  type CandlestickChartProps,
  parseCandles,
} from "./candlestick-chart/model";
export { type CandlestickTableProps, CandlestickTable } from "./candlestick-chart/table";

/**
 * Candlesticks (or OHLC bars) for prices over time, with a volume strip, a moving average and a
 * crosshair readout: the chart traders expect, built for a design system.
 *
 * - Rising candles are hollow and falling ones filled, and the readout names the move with an
 *   arrow, a sign and a percentage, so colour is never the only cue.
 * - Volume sits in its own strip under the prices, sharing the time axis (never a second y-axis).
 * - The readout above the chart always shows a candle: the latest one, or the one under the
 *   pointer / keyboard focus, with a crosshair and price and date tags on the axes.
 * - Zoom with Ctrl/⌘ + scroll, a trackpad pinch, a two-finger pinch on touch, the + / − keys
 *   or the buttons; pan with a mouse drag, a two-finger drag on touch (one finger reads the
 *   candles), scrolling sideways or Shift + arrows. The price axis eases to fit what's in view.
 * - Candles grow in from their middles, left to right, the first time the chart scrolls into
 *   view; the average draws in after them. Reduced motion: everything is drawn in place.
 *
 * Keyboard: Tab focuses the chart; Left and Right read the previous and next candle, Home and End jump to the first and last, Escape clears. With `zoom`: + and - zoom, 0 resets, Shift with Left or Right pans.
 * Accessibility: `role="figure"` named by the chart title, with the keyboard hint as its description (`aria-describedby`, and `aria-details` to the `ChartCard` table view); focusable only when interactive; rising candles are hollow and falling ones filled, and the readout names each move with an arrow, a sign and a percentage, so colour is never the only cue. `CandlestickTable` is the table view.
 * Glass and motion: the tooltip is a solid glass-look overlay (no backdrop blur). Reduced motion draws candles and zooms instantly.
 *
 * @example
 * ```tsx
 * import { CandlestickChart } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <CandlestickChart
 *       data={[
 *         { date: "2026-03-02", open: 100, high: 108, low: 97, close: 105, volume: 1200 },
 *         { date: "2026-03-03", open: 105, high: 110, low: 101, close: 103, volume: 980 },
 *         { date: "2026-03-04", open: 103, high: 112, low: 102, close: 111, volume: 1500 },
 *       ]}
 *       aria-label="ACME share price, March"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/candlestick
 */
export function CandlestickChart({
  data,
  mode = "candle",
  volume: volumeProp,
  average = 0,
  height = 300,
  volumeHeight = 64,
  upColor,
  downColor,
  averageColor = 1,
  format: formatProp,
  formatVolume: formatVolumeProp,
  formatDate,
  locale,
  timeZone,
  zoom = true,
  defaultRange,
  onRangeChange,
  emptyState,
  labels: labelOverrides,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<CandlestickChartProps>) {
  const t = { ...defaultCandlestickChartLabels, ...labelOverrides };
  const id = useId();
  const reduced = useSheenReducedMotion();
  const platform = useShortcutPlatform();
  const dark = useDarkScheme();
  const rootRef = useRef<HTMLDivElement>(null);
  const rootMerged = useMergedRef(rootRef, outerRef);
  const svgRef = useRef<SVGSVGElement>(null);
  const marksRef = useRef<SVGGElement>(null);
  const [measureRef, width] = useElementWidth<HTMLDivElement>();
  const play = useEntrance(rootRef, reduced);
  const { fromKeyboard, fromPointer, announce } = useInputSource();

  // New data (another symbol, a new range) is drawn in a transition: React yields while it
  // builds the candles, so the control that changed it responds at once.
  const shownData = useDeferredValue(data);
  // Marks are built once the chart nears the viewport, in a deferred render (see useDeferredDraw):
  // a page load or a ChartCard's Chart tab coming back paints the frame at once, the marks right after.
  const drawn = useDeferredDraw(rootRef);
  const candles = useMemo(() => parseCandles(shownData, average > 0 ? Math.floor(average) : 0), [shownData, average]);
  const count = candles.length;
  const showVolume = (volumeProp ?? candles.some((c) => c.v !== null)) && count > 0;

  // Number and date formats.
  const { priceFormat, dates, pctFormat } = useCandleFormats({ formatProp, locale, candles, count, timeZone });
  const volumeFormat = formatVolumeProp ?? defaultCompact(locale);
  const fullDate = (d: Date) => (Number.isNaN(d.getTime()) ? "" : formatDate ? formatDate(d) : dates.full.format(d));

  /* ---------- View window (zoom + pan) ---------- */

  const minSpan = Math.min(count, MIN_SPAN);
  const fit = (start: number, end: number) => {
    const span = clamp(end - start, Math.max(1, minSpan), Math.max(1, count));
    const s = clamp(start, 0, Math.max(0, count - span));
    return { start: s, end: s + span };
  };
  const dataKey = `${count}:${candles[0]?.date.getTime() ?? 0}:${candles[count - 1]?.date.getTime() ?? 0}`;
  const [viewState, setViewState] = useState<{ key: string; start: number; end: number } | null>(null);
  // The first view: `defaultRange` (or everything), narrowed on small screens so candles stay
  // at least ~5px apart (the latest end stays in view; zooming out shows the rest).
  const initial = defaultRange ? fit(defaultRange[0], defaultRange[1]) : { start: 0, end: count };
  const roomy = width > 0 && zoom ? Math.max(minSpan, Math.floor(Math.max(0, width - 110) / 5)) : Infinity;
  const view =
    viewState?.key === dataKey
      ? fit(viewState.start, viewState.end)
      : initial.end - initial.start > roomy
        ? fit(initial.end - roomy, initial.end)
        : initial;
  const span = Math.max(1e-6, view.end - view.start);
  const zoomed = span < count - 0.01;
  const commitView = (start: number, end: number) => {
    const next = fit(start, end);
    setViewState({ key: dataKey, ...next });
  };
  // The zoom glide: the displayed view (start, span) lives in MotionValues, `glidingRef` marks a glide in flight.
  const [glideFrom, setGlideFrom] = useState<{ start: number; end: number } | null>(null);
  const dS = useMotionValue(view.start);
  const dSpan = useMotionValue(span);
  const glidingRef = useRef(false);
  const stopGlide = () => {
    glidingRef.current = false;
    dS.stop();
    dSpan.stop();
    setGlideFrom(null);
  };
  // Direct changes (drag, pinch, wheel, keys) apply at once and end any zoom glide.
  const setView = (start: number, end: number) => {
    if (glidingRef.current) stopGlide();
    commitView(start, end);
  };
  const lastRange = useRef("");
  useEffect(() => {
    const key = `${Math.round(view.start)}-${Math.round(view.end)}`;
    if (key === lastRange.current) return;
    lastRange.current = key;
    onRangeChange?.([Math.round(view.start), Math.round(view.end)]);
  });

  /* ---------- Geometry ---------- */

  // While a zoom glides, the candles of both the old and the new view are drawn.
  const drawStart = glideFrom ? Math.min(view.start, glideFrom.start) : view.start;
  const drawEnd = glideFrom ? Math.max(view.end, glideFrom.end) : view.end;
  const first = Math.max(0, Math.floor(drawStart) - 1);
  const last = Math.min(count - 1, Math.ceil(drawEnd));
  const visible = useMemo(() => candles.slice(first, last + 1), [candles, first, last]);
  const { tLo, tHi, tV } = priceRange(candles, view, count);

  const ticks = useMemo(() => {
    const n = Math.max(2, Math.floor(height / 56));
    return niceTicks(tLo, tHi, n).filter((v) => v >= tLo && v <= tHi);
  }, [tLo, tHi, height]);

  const lastCandle = candles[count - 1];
  const axisChars = Math.max(
    ...ticks.map((v) => priceFormat(v).length),
    lastCandle ? priceFormat(lastCandle.c).length : 4,
  );
  const M = { top: 10, left: 4, right: clamp(Math.ceil(axisChars * AXIS_CH) + 22, 48, 104) };
  const innerW = Math.max(0, width - M.left - M.right);
  const priceH = height;
  const gap = showVolume ? 10 : 0;
  const volH = showVolume ? volumeHeight : 0;
  const axisH = 26;
  const svgH = M.top + priceH + gap + volH + axisH;
  const x = useCallback((i: number) => ((i + 0.5 - view.start) / span) * innerW, [view.start, span, innerW]);
  const step = innerW / span;
  const yP = useMemo(() => linear(tLo, tHi, priceH, 0), [tLo, tHi, priceH]);
  const yV = useMemo(() => linear(0, tV * 1.12, volH, 0), [tV, volH]);
  const priceAt = (py: number) => tLo + ((priceH - py) / Math.max(1, priceH)) * (tHi - tLo);
  const rawBodyW = clamp(step * 0.64, 1, 24);
  const bodyW = step - rawBodyW < 2 ? Math.max(1, step - 2) : rawBodyW;
  const hollow = bodyW >= 4; // below 4px a hollow body can't be told apart: fill both
  const up = upColor ? slotColor(upColor) : UP;
  const down = downColor ? slotColor(downColor) : DOWN;
  const maColor = slotColor(averageColor);
  const colorOf = useCallback((c: Parsed) => (c.c >= c.o ? up : down), [up, down]);
  const perCandle = Math.min(0.02, 0.6 / Math.max(1, visible.length));

  /** One candle (or OHLC bar): its wick and body, in its rising / falling colour. */
  const drawCandle = useCallback(
    (c: Parsed, i: number) => candleShape(c, x(i), colorOf(c), { mode, step, bodyW, hollow, yP }),
    [x, yP, colorOf, mode, step, bodyW, hollow],
  );
  const volumeBar = useCallback(
    (c: Parsed, i: number, strength: number) => volumeBarShape(c, x(i), strength, colorOf(c), { volH, bodyW, yV }),
    [x, yV, volH, bodyW, colorOf],
  );

  // The marks depend on the view and the price scale only, never on the candle being read:
  // built once per layout, so scrubbing re-renders just the crosshair and the active candle.
  const candleMarks = useMemo(
    () =>
      !drawn
        ? null
        : visible.map((c, k) => (
            <g
              key={first + k}
              data-delay={reduced ? undefined : (k * perCandle).toFixed(3)}
              style={{ transformBox: "fill-box", transformOrigin: "center" }}
            >
              {drawCandle(c, first + k)}
            </g>
          )),
    [visible, first, drawCandle, reduced, perCandle, drawn],
  );
  const volumeMarks = useMemo(
    () =>
      showVolume && drawn
        ? visible.map((c, k) => {
            const bar = volumeBar(c, first + k, 45);
            return bar ? (
              <path
                key={first + k}
                data-delay={reduced ? undefined : (0.1 + k * perCandle).toFixed(3)}
                d={bar.d}
                fill={bar.fill}
                style={{ transformBox: "fill-box", transformOrigin: "center bottom" }}
              />
            ) : null;
          })
        : null,
    [visible, first, volumeBar, showVolume, reduced, perCandle, drawn],
  );

  /* ---------- Interaction state ---------- */

  const [active, setActive] = useState<number | null>(null);
  const [crossY, setCrossY] = useState<number | null>(null);
  const [hint, setHint] = useState(false);
  const act = active !== null && active < count ? active : null;
  const shownCandle = act !== null ? candles[act] : lastCandle;

  // The latest view, size and actions for the native listeners below (bound once), so a wheel
  // or a trackpad pinch always acts on the current data, even after it changes.
  const live = useRef<LiveView>({
    view,
    innerW,
    count,
    zoom,
    left: M.left,
    setView: (_s: number, _e: number): void => undefined,
    zoomBy: (_f: number, _a: number): void => undefined,
    nudgeMoving: (): void => undefined,
  });

  // While the view is being dragged, pinched or wheeled (or glides), the average line drops its
  // glow, so nothing has to re-blur on those frames.
  const [moving, setMoving] = useState(false);
  const movingTimer = useRef(0);
  const nudgeMoving = () => {
    setMoving(true);
    window.clearTimeout(movingTimer.current);
    movingTimer.current = window.setTimeout(() => setMoving(false), 180);
  };
  useEffect(() => () => window.clearTimeout(movingTimer.current), []);

  /*
   * What is on screen, as MotionValues: the view (start, span) and the price and volume ranges.
   * React draws the marks once, on the target view and ranges; `applyDisplay` maps them onto the
   * displayed ones with a transform per layer (and moves the axis labels), so a zoom glide or an
   * easing axis never re-renders React per frame (FLIP, for SVG). x follows the view at once,
   * except while a zoom glides; the ranges always ease (instantly under reduced motion).
   */
  const dLo = useMotionValue(tLo);
  const dHi = useMotionValue(tHi);
  const dV = useMotionValue(tV);
  const priceLayerRef = useRef<SVGGElement>(null);
  const volumeLayerRef = useRef<SVGGElement>(null);
  const dateAxisRef = useRef<SVGGElement>(null);
  const lastLineRef = useRef<SVGGElement>(null);
  const lastPillRef = useRef<SVGGElement>(null);
  const tickRefs = useRef(new Map<number, SVGGElement>());
  const target = useRef({
    start: view.start,
    span,
    lo: tLo,
    hi: tHi,
    v: tV,
    w: innerW,
    h: priceH,
    volH,
    last: null as number | null,
    right: innerW + 2,
    pillH: 18,
  });
  const [applyDisplay] = useState(
    () => () =>
      paintDisplay(target.current, {
        dS,
        dSpan,
        dLo,
        dHi,
        dV,
        priceLayer: priceLayerRef,
        volumeLayer: volumeLayerRef,
        dateAxis: dateAxisRef,
        lastLine: lastLineRef,
        lastPill: lastPillRef,
        ticks: tickRefs,
      }),
  );
  // Several MotionValues change per frame: apply once, in Motion's render step.
  useEffect(() => {
    const schedule = () => frame.render(applyDisplay);
    const offs = [dS, dSpan, dLo, dHi, dV].map((mv) => mv.on("change", schedule));
    return () => {
      offs.forEach((off) => off());
      cancelFrame(applyDisplay);
      [dS, dSpan, dLo, dHi, dV].forEach((mv) => mv.stop());
    };
  }, [dS, dSpan, dLo, dHi, dV, applyDisplay]);
  const sized = width > 0;
  const hasCandles = count > 0;
  useLayoutEffect(() => {
    const prev = target.current;
    target.current = {
      start: view.start,
      span,
      lo: tLo,
      hi: tHi,
      v: tV,
      w: innerW,
      h: priceH,
      volH,
      last: lastCandle ? yP(lastCandle.c) : null,
      right: innerW + 2,
      pillH: PILL_H,
    };
    if (!glidingRef.current) {
      dS.jump(view.start);
      dSpan.jump(span);
    }
    if (prev.lo !== tLo || prev.hi !== tHi || prev.v !== tV) {
      if (reduced || !sized) {
        dLo.jump(tLo);
        dHi.jump(tHi);
        dV.jump(tV);
      } else {
        const opts = { duration: duration.base, ease: ease.out };
        animate(dLo, tLo, opts);
        animate(dHi, tHi, opts);
        animate(dV, tV, opts);
      }
    }
    // The marks were just drawn on the new targets: map them onto the screen before paint.
    applyDisplay();
  });

  const zoomBy = (factor: number, anchor: number) => {
    const { view: v, count: n } = live.current;
    const s = v.end - v.start;
    const next = clamp(s * factor, Math.max(1, Math.min(n, MIN_SPAN)), n);
    const k = next / s;
    setView(anchor - (anchor - v.start) * k, anchor - (anchor - v.start) * k + next);
  };
  useLayoutEffect(() => {
    live.current = { view, innerW, count, zoom, left: M.left, setView, zoomBy, nudgeMoving };
  });
  /** Zoom buttons and the 0 key: the new view is drawn once, then glides into place by transform. */
  const glide = (start: number, end: number) => {
    const to = fit(start, end);
    if (reduced) {
      setView(to.start, to.end);
      return;
    }
    const fromStart = dS.get();
    glidingRef.current = true;
    setGlideFrom({ start: fromStart, end: fromStart + dSpan.get() });
    commitView(to.start, to.end);
    setMoving(true);
    const opts = { duration: duration.slow, ease: ease.out };
    animate(dS, to.start, opts);
    animate(dSpan, to.end - to.start, {
      ...opts,
      onComplete: () => {
        glidingRef.current = false;
        setGlideFrom(null);
        setMoving(false);
      },
    });
  };

  useWheelZoom(svgRef, live, setHint, [sized, hasCandles]);

  const { onPointerDown, onPointerMove, onPointerEnd, onKeyDown, gesture } = useCandleInteraction({
    svgRef,
    view,
    span,
    count,
    zoom,
    zoomed,
    minSpan,
    innerW,
    priceH,
    margin: M,
    active: act,
    setActive,
    setCrossY,
    setView,
    zoomBy,
    glide,
    nudgeMoving,
    fromPointer,
    fromKeyboard,
  });
  // Entrance: candles grow from their middles (volume from the floor), left to right.
  useStaggerEntrance(
    marksRef,
    play && drawn && width > 0 && count > 0,
    reduced,
    [
      { transform: "scaleY(0)", opacity: 0 },
      { transform: "scaleY(1)", opacity: 1 },
    ],
    duration.slow * 1000,
  );

  if (count === 0) {
    return (
      <div ref={measureRef} className={cn("w-full", className)}>
        <ChartEmpty height={height + (volumeProp ? volumeHeight : 0) + 40} aria-label={ariaLabel}>
          {emptyState ?? t.empty}
        </ChartEmpty>
      </div>
    );
  }

  /* ---------- Readout ---------- */

  const changeOf = (c: Parsed) => (c.prev === null ? c.c - c.o : c.c - c.prev);
  const base = (c: Parsed) => c.prev ?? c.o;
  const move = shownCandle ? changeOf(shownCandle) : 0;
  const moveRatio = shownCandle && base(shownCandle) !== 0 ? move / base(shownCandle) : 0;
  const dir = move > 0 ? "up" : move < 0 ? "down" : "flat";
  const sign = (n: number) => (n > 0 ? "+" : n < 0 ? "−" : "");
  const moveText = `${sign(move)}${priceFormat(Math.abs(move))} (${pctFormat.format(moveRatio).replace("-", "−")})`;
  const widest = Math.max(...candles.map((c) => priceFormat(c.h).length), 4);
  const announceText =
    act !== null && shownCandle
      ? `${fullDate(shownCandle.date)}: ${t.open} ${priceFormat(shownCandle.o)}, ${t.high} ${priceFormat(shownCandle.h)}, ${t.low} ${priceFormat(shownCandle.l)}, ${t.close} ${priceFormat(shownCandle.c)}, ${dir === "up" ? t.up : dir === "down" ? t.down : t.unchanged} ${pctFormat.format(Math.abs(moveRatio)).replace(/^\+/, "")}${shownCandle.v !== null ? `, ${t.volume} ${volumeFormat(shownCandle.v)}` : ""}${shownCandle.ma !== null ? `, ${t.average(average)} ${priceFormat(shownCandle.ma)}` : ""}`
      : "";

  /* ---------- Drawing ---------- */

  // Date labels on every k-th candle (by index, so they slide with the candles when panning).
  const labelW = Math.max(...visible.map((c) => dates.axis.format(c.date).length), 3) * AXIS_CH + 16;
  const every = Math.max(1, Math.ceil(labelW / Math.max(1e-6, step)));
  const lastUp = lastCandle ? lastCandle.c >= (lastCandle.prev ?? lastCandle.o) : true;
  const lastColor = lastUp ? up : down;
  const maPath = (() => {
    if (!(average > 0)) return "";
    let d = "";
    for (let i = first; i <= last; i++) {
      const m = candles[i]?.ma;
      if (m === null || m === undefined) continue;
      d += `${d ? "L" : "M"}${x(i).toFixed(1)},${yP(m).toFixed(1)} `;
    }
    return d;
  })();
  // The candle being read is redrawn over the (dimmed) memoised marks; its volume bar too, so
  // the two layers add up to ~80% strength.
  const activeParsed = act !== null && act >= first && act <= last ? candles[act] : undefined;
  const activeVolume = activeParsed && act !== null && showVolume ? volumeBar(activeParsed, act, 64) : null;
  const crossPrice = crossY !== null ? priceAt(crossY) : act !== null && shownCandle ? shownCandle.c : null;
  const crossPy = crossY ?? (crossPrice !== null ? yP(crossPrice) : null);
  const pillH = PILL_H;
  // The last-price tag steps aside while the crosshair's price tag would cover it.
  const lastPy = lastCandle ? clamp(yP(lastCandle.c), pillH / 2, priceH - pillH / 2) : null;
  const crossPillPy = crossPy !== null && crossPrice !== null ? clamp(crossPy, pillH / 2, priceH - pillH / 2) : null;
  const lastTagHidden = lastPy !== null && crossPillPy !== null && Math.abs(lastPy - crossPillPy) < pillH + 2;
  const dateText = shownCandle && act !== null ? dates.axis.format(shownCandle.date) : "";
  const dateW = dateText.length * AXIS_CH + 14;
  // Left edge of the crosshair's date tag (kept inside the plot), and its centre for collisions.
  const dateTagLeft = act !== null ? clamp(x(act) - dateW / 2, 0, Math.max(0, innerW - dateW)) : 0;
  const dateTagX = act !== null ? dateTagLeft + dateW / 2 : null;

  return (
    <div {...rest} ref={rootMerged} className={cn("relative flex w-full min-w-0 flex-col gap-2", className)}>
      <CandleReadout
        candle={shownCandle}
        dateText={shownCandle ? fullDate(shownCandle.date) : ""}
        labels={t}
        widest={widest}
        priceFormat={priceFormat}
        volumeFormat={volumeFormat}
        dir={dir}
        moveText={moveText}
        showVolume={showVolume}
        average={average}
        maColor={maColor}
        zoomButtons={zoom && count > 2}
        zoomed={zoomed}
        canZoomIn={span > minSpan + 0.01}
        onZoomOut={() => glide((view.start + view.end) / 2 - span * 0.75, (view.start + view.end) / 2 + span * 0.75)}
        onZoomIn={() => glide((view.start + view.end) / 2 - span * 0.35, (view.start + view.end) / 2 + span * 0.35)}
        onReset={() => glide(0, count)}
      />

      <div ref={measureRef} className="relative w-full" style={{ height: svgH }}>
        {width > 0 && (
          <ChartFigure
            as="svg"
            ref={svgRef}
            width={width}
            height={svgH}
            label={ariaLabel}
            description={resolveInstructions(t.instructions)}
            tabIndex={0}
            onKeyDown={onKeyDown}
            onBlur={() => {
              setActive(null);
              setCrossY(null);
            }}
            className={cn("rounded-sheen-sm select-none", chartFocusClass)}
            // Time runs left to right in every locale. Vertical swipes scroll the page; one finger
            // reads the candles and two fingers pinch or pan, never zooming the page.
            style={{ direction: "ltr", touchAction: "pan-y pinch-zoom" }}
          >
            <defs>
              <clipPath id={`${id}-price`}>
                <rect x={0} y={-4} width={innerW} height={priceH + 8} />
              </clipPath>
              <clipPath id={`${id}-vol`}>
                <rect x={0} y={0} width={innerW} height={volH} />
              </clipPath>
            </defs>
            <g aria-hidden transform={`translate(${M.left},${M.top})`}>
              {/* Price grid + axis (right, as traders expect). */}
              {/* Positioned by applyDisplay, so they follow the easing price range. */}
              {ticks.map((tk) => (
                <g
                  key={tk}
                  ref={(el) => {
                    if (!el) return;
                    tickRefs.current.set(tk, el);
                    return () => {
                      tickRefs.current.delete(tk);
                    };
                  }}
                >
                  <line x2={innerW} stroke="var(--sheen-chart-grid)" />
                  <text x={innerW + 8} dy="0.32em" className="fill-sheen-fg-muted text-2xs tabular-nums">
                    {priceFormat(tk)}
                  </text>
                </g>
              ))}
              {showVolume && (
                <line
                  x1={0}
                  x2={innerW}
                  y1={priceH + gap + volH}
                  y2={priceH + gap + volH}
                  stroke="var(--sheen-border)"
                />
              )}
              {/* Last price: a dashed level across the plot (placed by applyDisplay). */}
              {lastCandle && (
                <g ref={lastLineRef}>
                  <line
                    x1={0}
                    x2={innerW}
                    stroke={lastColor}
                    strokeOpacity={0.7}
                    strokeDasharray="3 3"
                    className="forced-color-adjust-none"
                  />
                </g>
              )}

              <g ref={marksRef} className="forced-color-adjust-none">
                <g clipPath={`url(#${id}-price)`}>
                  {/* Drawn on the target view and range; applyDisplay maps this layer onto the screen. */}
                  <g ref={priceLayerRef}>
                    {/* Every candle (memoised), stepping back while one is read… */}
                    <g
                      className="motion-ok:transition-opacity motion-ok:duration-(--sheen-duration-fast)"
                      style={{ opacity: act !== null ? 0.55 : 1 }}
                    >
                      {candleMarks}
                    </g>
                    {/* …and the one being read, redrawn on top at full strength with a soft glow (dark theme). */}
                    {activeParsed && act !== null && (
                      <g pointerEvents="none" style={{ filter: markGlow(colorOf(activeParsed), 6) }}>
                        {drawCandle(activeParsed, act)}
                      </g>
                    )}
                    {maPath && drawn && (
                      <motion.path
                        d={maPath}
                        fill="none"
                        stroke={maColor}
                        strokeWidth={2}
                        strokeLinejoin="round"
                        strokeLinecap="round"
                        initial={reduced ? false : { pathLength: 0 }}
                        animate={{ pathLength: play ? 1 : 0 }}
                        transition={{
                          pathLength: {
                            duration: reduced ? 0 : duration.slower * 1.4,
                            ease: ease.out,
                            delay: reduced ? 0 : 0.35,
                          },
                        }}
                        // A soft glow in the dark theme only, and never while the view moves (no re-blur per frame).
                        style={{
                          filter:
                            dark && !moving
                              ? `drop-shadow(0 0 4px color-mix(in oklab, ${maColor} 45%, transparent))`
                              : undefined,
                        }}
                      />
                    )}
                  </g>
                </g>

                {showVolume && (
                  <g transform={`translate(0,${priceH + gap})`} clipPath={`url(#${id}-vol)`}>
                    <g ref={volumeLayerRef}>
                      {volumeMarks}
                      {activeVolume && <path pointerEvents="none" d={activeVolume.d} fill={activeVolume.fill} />}
                    </g>
                  </g>
                )}
              </g>

              {/* Volume scale, haloed so it reads over the bars. */}
              {showVolume && (
                <text
                  x={4}
                  y={priceH + gap + 11}
                  className="fill-sheen-fg-muted text-2xs"
                  stroke="var(--sheen-chart-surface)"
                  strokeWidth={3}
                  paintOrder="stroke"
                  strokeLinejoin="round"
                >
                  {t.volumeShort} {volumeFormat(tV)}
                </text>
              )}

              {/* Date axis: every k-th candle, sliding with the candles. Labels under the
                  crosshair's date tag step aside, so the two never overprint. */}
              <g ref={dateAxisRef}>
                {visible.map((c, k) => {
                  const i = first + k;
                  if (i % every !== 0) return null;
                  const px = x(i);
                  if (px < 12 || px > innerW - 12) return null;
                  if (dateTagX !== null) {
                    const w = dates.axis.format(c.date).length * AXIS_CH;
                    if (Math.abs(px - dateTagX) < (w + dateW) / 2 + 4) return null;
                  }
                  return (
                    <text
                      key={i}
                      x={px}
                      y={priceH + gap + volH + 18}
                      textAnchor="middle"
                      className="fill-sheen-fg-muted text-2xs"
                      // While a zoom glides the axis is scaled sideways: the text is scaled back.
                      style={{
                        transform: "scaleX(var(--inv-x, 1))",
                        transformBox: "fill-box",
                        transformOrigin: "center",
                      }}
                    >
                      {dates.axis.format(c.date)}
                    </text>
                  );
                })}
              </g>

              {/* Last price tag on the axis, in the direction's colour with ink-coloured text. */}
              {lastCandle && (
                <g ref={lastPillRef} style={{ opacity: lastTagHidden ? 0 : 1 }}>
                  <rect
                    width={M.right - 4}
                    height={pillH}
                    rx={5}
                    fill="var(--sheen-chart-surface)"
                    stroke={lastColor}
                    strokeWidth={1.5}
                    className="forced-color-adjust-none"
                  />
                  <text x={6} y={pillH / 2} dy="0.34em" className="fill-sheen-fg text-2xs font-semibold tabular-nums">
                    {priceFormat(lastCandle.c)}
                  </text>
                </g>
              )}

              {act !== null && (
                <Crosshair
                  x={x(act)}
                  priceH={priceH}
                  gap={gap}
                  volH={volH}
                  innerW={innerW}
                  tagW={M.right - 4}
                  crossPy={crossPy}
                  crossPrice={crossPrice}
                  priceText={priceFormat}
                  dateTagLeft={dateTagLeft}
                  dateW={dateW}
                  dateText={dateText}
                />
              )}

              {/* Hit area over both panels: scrub, drag to pan, pinch to zoom (vertical swipes still scroll). */}
              <rect
                width={innerW}
                height={priceH + gap + volH}
                fill="transparent"
                className={zoom && zoomed ? "cursor-grab active:cursor-grabbing" : "cursor-crosshair"}
                onPointerDown={onPointerDown}
                onPointerMove={onPointerMove}
                onPointerUp={onPointerEnd}
                onPointerCancel={onPointerEnd}
                onPointerLeave={(e) => {
                  if (e.pointerType !== "mouse" || gesture.current) return;
                  setActive(null);
                  setCrossY(null);
                }}
              />
            </g>
          </ChartFigure>
        )}
        {hint && zoom && (
          <p
            aria-hidden
            className={cn(
              solidOverlayClass,
              "pointer-events-none absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-sheen-full px-3.5 py-2 text-xs font-medium whitespace-nowrap",
            )}
          >
            {t.zoomHint(platform === "mac" ? "⌘" : "Ctrl")}
          </p>
        )}
      </div>
      <ChartAnnouncer text={announce(announceText)} />
    </div>
  );
}

import { clamp } from "../chart-utils";
import { PILL_H as pillH } from "./model";

/** The crosshair: a vertical line, a horizontal one at the read price, and the price and date tags on the axes. */
export function Crosshair({
  x,
  priceH,
  gap,
  volH,
  innerW,
  tagW,
  crossPy,
  crossPrice,
  priceText,
  dateTagLeft,
  dateW,
  dateText,
}: {
  /** Horizontal position of the read candle. */
  x: number;
  priceH: number;
  gap: number;
  volH: number;
  innerW: number;
  /** Width of the price tag on the axis. */
  tagW: number;
  crossPy: number | null;
  crossPrice: number | null;
  priceText: (value: number) => string;
  dateTagLeft: number;
  dateW: number;
  dateText: string;
}) {
  return (
    <g pointerEvents="none">
      <line x1={x} x2={x} y1={0} y2={priceH + gap + volH} stroke="var(--sheen-fg-subtle)" strokeDasharray="2 3" />
      {crossPy !== null && crossPrice !== null && (
        <>
          <line x1={0} x2={innerW} y1={crossPy} y2={crossPy} stroke="var(--sheen-fg-subtle)" strokeDasharray="2 3" />
          <g transform={`translate(${innerW + 2},${clamp(crossPy, pillH / 2, priceH - pillH / 2) - pillH / 2})`}>
            <rect width={tagW} height={pillH} rx={5} className="fill-sheen-fg" />
            <text
              x={6}
              y={pillH / 2}
              dy="0.34em"
              className="text-2xs font-semibold tabular-nums"
              style={{ fill: "var(--sheen-chart-surface)" }}
            >
              {priceText(crossPrice)}
            </text>
          </g>
        </>
      )}
      <g transform={`translate(${dateTagLeft},${priceH + gap + volH + 5})`}>
        <rect width={dateW} height={pillH} rx={5} className="fill-sheen-fg" />
        <text
          x={dateW / 2}
          y={pillH / 2}
          dy="0.34em"
          textAnchor="middle"
          className="text-2xs font-semibold"
          style={{ fill: "var(--sheen-chart-surface)" }}
        >
          {dateText}
        </text>
      </g>
    </g>
  );
}

"use client";

import { useMemo } from "react";

import { itemAt } from "../chart-utils";
import { safeNumberFormat } from "../category-bar";
import { dateFormats, type Parsed } from "./model";

/** The price, percent and date formatters of a candlestick chart. @internal */
export function useCandleFormats(o: {
  formatProp: ((v: number) => string) | undefined;
  locale: string | undefined;
  candles: Parsed[];
  count: number;
  timeZone: string | undefined;
}) {
  const { formatProp, locale, candles, count, timeZone } = o;
  const priceFormat = useMemo(() => {
    if (formatProp) return formatProp;
    const nf = safeNumberFormat(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return (n: number) => nf.format(n).replace("-", "−");
  }, [formatProp, locale]);
  const intraday = useMemo(() => {
    if (count < 2) return false;
    const gaps = candles
      .slice(1)
      .map((c, i) => c.date.getTime() - itemAt(candles, i).date.getTime())
      .sort((a, b) => a - b);
    return (gaps[Math.floor(gaps.length / 2)] ?? 0) < 20 * 3_600_000;
  }, [candles, count]);
  const dates = useMemo(() => dateFormats(locale, intraday, timeZone), [locale, intraday, timeZone]);
  const pctFormat = useMemo(
    () =>
      safeNumberFormat(locale, {
        style: "percent",
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
        signDisplay: "exceptZero",
      }),
    [locale],
  );
  return { priceFormat, dates, pctFormat };
}

/**
 * The target price and volume ranges of the visible window, padded. The marks are drawn on them; while
 * the axes ease (and while a zoom glides), a transform maps them onto what is on screen.
 * @internal
 */
export function priceRange(candles: readonly Parsed[], view: { start: number; end: number }, count: number) {
  let lo = Infinity;
  let hi = -Infinity;
  let vmax = 0;
  for (let i = Math.max(0, Math.floor(view.start)); i < Math.min(count, Math.ceil(view.end)); i++) {
    const c = itemAt(candles, i);
    lo = Math.min(lo, c.l, c.ma ?? c.l);
    hi = Math.max(hi, c.h, c.ma ?? c.h);
    vmax = Math.max(vmax, c.v ?? 0);
  }
  if (!Number.isFinite(lo)) [lo, hi] = [0, 1];
  const pad = (hi - lo) * 0.08 || Math.abs(hi) * 0.02 || 1;
  return { tLo: lo - pad, tHi: hi + pad, tV: vmax || 1 };
}

import type { MotionValue } from "motion/react";
import type { RefObject } from "react";

import { clamp } from "../chart-utils";

/** The displayed view and ranges the candlestick maps its marks onto. @internal */
export type DisplayTarget = {
  start: number;
  span: number;
  lo: number;
  hi: number;
  v: number;
  w: number;
  h: number;
  volH: number;
  last: number | null;
  right: number;
  pillH: number;
};

/** The animated values and layer elements `paintDisplay` reads and writes. @internal */
export type DisplayParts = {
  dS: MotionValue<number>;
  dSpan: MotionValue<number>;
  dLo: MotionValue<number>;
  dHi: MotionValue<number>;
  dV: MotionValue<number>;
  priceLayer: RefObject<SVGGElement | null>;
  volumeLayer: RefObject<SVGGElement | null>;
  dateAxis: RefObject<SVGGElement | null>;
  lastLine: RefObject<SVGGElement | null>;
  lastPill: RefObject<SVGGElement | null>;
  ticks: RefObject<Map<number, SVGGElement>>;
};

const setAttr = (el: SVGGElement | null, value: string) => {
  if (!el) return;
  if (value) el.setAttribute("transform", value);
  else el.removeAttribute("transform");
};
/**
 * Map the marks, drawn once on the target view and ranges, onto the displayed ones with a transform per
 * layer (and move the axis labels, tick lines and the last-price tag), so a glide never re-renders React.
 * @internal
 */
export function paintDisplay(g: DisplayTarget, p: DisplayParts) {
  const { dS, dSpan, dLo, dHi, dV } = p;
  const sp = Math.max(1e-6, dSpan.get());
  const lo = dLo.get();
  const hi = dHi.get();
  const range = Math.max(1e-9, hi - lo);
  const ax = g.span / sp;
  const bx = ((g.start - dS.get()) * g.w) / sp;
  const ay = (g.hi - g.lo) / range;
  const by = (g.h * (hi - g.hi)) / range;
  const av = g.v / Math.max(1e-9, dV.get());
  const bv = g.volH * (1 - av);
  const same = (k: number, b: number) => Math.abs(k - 1) < 1e-5 && Math.abs(b) < 0.01;
  const matrix = (a: number, d: number, e: number, f: number) =>
    same(a, e) && same(d, f) ? "" : `matrix(${a.toFixed(5)} 0 0 ${d.toFixed(5)} ${e.toFixed(2)} ${f.toFixed(2)})`;
  setAttr(p.priceLayer.current, matrix(ax, ay, bx, by));
  setAttr(p.volumeLayer.current, matrix(ax, av, bx, bv));
  // Date labels slide with the candles, scaled back so their text never stretches.
  const axis = p.dateAxis.current;
  if (axis) {
    setAttr(axis, same(ax, bx) ? "" : `matrix(${ax.toFixed(5)} 0 0 1 ${bx.toFixed(2)} 0)`);
    axis.style.setProperty("--inv-x", (1 / ax).toFixed(5));
  }
  // Price gridlines and labels sit on the displayed range; those outside it hide.
  for (const [value, el] of p.ticks.current) {
    const y = (g.h * (hi - value)) / range;
    el.setAttribute("transform", `translate(0 ${y.toFixed(2)})`);
    el.style.opacity = y >= -0.5 && y <= g.h + 0.5 ? "" : "0";
  }
  if (g.last !== null) {
    const y = ay * g.last + by;
    setAttr(p.lastLine.current, `translate(0 ${y.toFixed(2)})`);
    setAttr(
      p.lastPill.current,
      `translate(${g.right} ${(clamp(y, g.pillH / 2, g.h - g.pillH / 2) - g.pillH / 2).toFixed(2)})`,
    );
  }
}

"use client";

import { useRef } from "react";

import { clamp } from "../chart-utils";

/** What the candlestick's pointer and keyboard handlers read and change. @internal */
export type CandleInteraction = {
  svgRef: React.RefObject<SVGSVGElement | null>;
  view: { start: number; end: number };
  span: number;
  count: number;
  zoom: boolean;
  zoomed: boolean;
  minSpan: number;
  innerW: number;
  priceH: number;
  margin: { top: number; left: number };
  active: number | null;
  setActive: (i: number | null) => void;
  setCrossY: (y: number | null) => void;
  setView: (start: number, end: number) => void;
  zoomBy: (factor: number, anchor: number) => void;
  glide: (start: number, end: number) => void;
  nudgeMoving: () => void;
  fromPointer: () => void;
  fromKeyboard: () => void;
};

/**
 * The candlestick's pointer (hover, drag-pan, two-finger pinch) and keyboard handlers. The pointer
 * and gesture bookkeeping lives in refs: they change on every move and never render by themselves.
 * @internal
 */
export function useCandleInteraction(o: CandleInteraction) {
  const { svgRef, view, span, count, zoom, zoomed, minSpan, innerW, priceH, margin: M, active: act } = o;
  const { setActive, setCrossY, setView, zoomBy, glide, nudgeMoving, fromPointer, fromKeyboard } = o;
  const pointers = useRef(new Map<number, { x: number; y: number }>());
  const gesture = useRef<{
    kind: "drag" | "pinch";
    x0: number;
    dist0: number;
    start: number;
    end: number;
    moved: boolean;
  } | null>(null);
  const indexAt = (px: number) => clamp(Math.floor(view.start + (px / Math.max(1, innerW)) * span), 0, count - 1);

  const local = (e: React.PointerEvent) => {
    const rect = svgRef.current?.getBoundingClientRect() ?? { left: 0, top: 0 };
    return { x: e.clientX - rect.left - M.left, y: e.clientY - rect.top - M.top };
  };
  const scrub = (px: number, py: number) => {
    setActive(indexAt(px));
    setCrossY(py >= 0 && py <= priceH ? py : null);
  };
  function onPointerDown(e: React.PointerEvent<SVGRectElement>) {
    fromPointer();
    const p = local(e);
    pointers.current.set(e.pointerId, p);
    if (typeof e.currentTarget.setPointerCapture === "function") e.currentTarget.setPointerCapture(e.pointerId);
    const [a, b] = [...pointers.current.values()];
    if (pointers.current.size === 2 && zoom && a && b) {
      gesture.current = {
        kind: "pinch",
        x0: (a.x + b.x) / 2,
        dist0: Math.max(10, Math.abs(a.x - b.x)),
        start: view.start,
        end: view.end,
        moved: true,
      };
      return;
    }
    if (e.pointerType === "mouse" && e.button === 0 && zoom && zoomed) {
      gesture.current = { kind: "drag", x0: p.x, dist0: 0, start: view.start, end: view.end, moved: false };
    }
    scrub(p.x, p.y);
  }
  function onPointerMove(e: React.PointerEvent<SVGRectElement>) {
    fromPointer();
    const p = local(e);
    if (pointers.current.has(e.pointerId)) pointers.current.set(e.pointerId, p);
    const g = gesture.current;
    const [a, b] = [...pointers.current.values()];
    if (g?.kind === "pinch" && a && b) {
      const mid = (a.x + b.x) / 2;
      const dist = Math.max(10, Math.abs(a.x - b.x));
      const span0 = g.end - g.start;
      const nextSpan = clamp(span0 * (g.dist0 / dist), Math.max(1, minSpan), count);
      // Keep the candle under the fingers' midpoint under it, then follow the midpoint.
      const anchor = g.start + (g.x0 / Math.max(1, innerW)) * span0;
      const start = anchor - (mid / Math.max(1, innerW)) * nextSpan;
      nudgeMoving();
      setView(start, start + nextSpan);
      return;
    }
    if (g?.kind === "drag") {
      const dx = p.x - g.x0;
      if (Math.abs(dx) > 3) g.moved = true;
      if (g.moved) {
        const di = (-dx / Math.max(1, innerW)) * (g.end - g.start);
        nudgeMoving();
        setView(g.start + di, g.end + di);
      }
    }
    scrub(p.x, p.y);
  }
  function onPointerEnd(e: React.PointerEvent<SVGRectElement>) {
    pointers.current.delete(e.pointerId);
    if (pointers.current.size < 2 && gesture.current?.kind === "pinch") gesture.current = null;
    if (pointers.current.size === 0) gesture.current = null;
  }

  function onKeyDown(e: React.KeyboardEvent) {
    fromKeyboard();
    const cur = act ?? Math.min(count - 1, Math.floor(view.end) - 1);
    const keep = (i: number) => {
      setActive(i);
      setCrossY(null);
      // Keep the active candle in view: the window follows it.
      if (i < view.start) setView(i, i + span);
      else if (i + 1 > view.end) setView(i + 1 - span, i + 1);
    };
    if (e.shiftKey && (e.key === "ArrowLeft" || e.key === "ArrowRight") && zoom) {
      const di = (e.key === "ArrowLeft" ? -1 : 1) * Math.max(1, span * 0.15);
      setView(view.start + di, view.end + di);
    } else if (e.key === "ArrowLeft") keep(act === null ? cur : Math.max(0, cur - 1));
    else if (e.key === "ArrowRight") keep(act === null ? cur : Math.min(count - 1, cur + 1));
    else if (e.key === "Home") keep(0);
    else if (e.key === "End") keep(count - 1);
    else if ((e.key === "+" || e.key === "=") && zoom)
      zoomBy(0.7, act !== null ? act + 0.5 : (view.start + view.end) / 2);
    else if ((e.key === "-" || e.key === "_") && zoom)
      zoomBy(1 / 0.7, act !== null ? act + 0.5 : (view.start + view.end) / 2);
    else if (e.key === "0" && zoom) glide(0, count);
    else if (e.key === "Escape" && act !== null) setActive(null);
    else return;
    e.preventDefault();
  }

  return { onPointerDown, onPointerMove, onPointerEnd, onKeyDown, gesture };
}

"use client";

import { type ReactNode } from "react";

import { type ChartColor, type ChartInstructions } from "../chart-utils";
import { safeDateFormat } from "../category-bar";

/* ---------- Types ---------- */

/** One candlestick: its period start and the open, high, low and close prices, plus an optional volume. */
export type Candle = {
  /** When the period starts: a Date, an ISO string or a timestamp. Oldest first. */
  date: Date | string | number;
  open: number;
  high: number;
  low: number;
  close: number;
  /** Traded volume, drawn in its own strip under the prices. */
  volume?: number;
};

/**
 * Every string CandlestickChart speaks or shows, so it can be translated: pass a `Partial` as the
 * `labels` prop. Entries that need a value are functions.
 */
export type CandlestickChartLabels = {
  instructions: ChartInstructions;
  open: string;
  high: string;
  low: string;
  close: string;
  volume: string;
  /** Short names in the readout. */
  openShort: string;
  highShort: string;
  lowShort: string;
  closeShort: string;
  volumeShort: string;
  /** Spoken direction of a candle against the previous close. */
  up: string;
  down: string;
  unchanged: string;
  /** Moving average name, e.g. "MA 20". */
  average: (period: number) => string;
  zoomIn: string;
  zoomOut: string;
  resetZoom: string;
  /** Shown briefly when someone scrolls over the chart without the zoom key held. */
  zoomHint: (key: string) => string;
  /** Table headers. */
  date: string;
  change: string;
  empty: string;
  /** Button under a long table, e.g. "Show all 160 rows". */
  showAll: (rows: number) => string;
};

/**
 * The built-in English strings of CandlestickChart; spread it into your own `labels` and change what
 * you need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultCandlestickChartLabels: CandlestickChartLabels = {
  instructions:
    "Use left and right arrow keys to read each candle, plus and minus to zoom, Shift with the arrows to pan.",
  open: "open",
  high: "high",
  low: "low",
  close: "close",
  volume: "volume",
  openShort: "O",
  highShort: "H",
  lowShort: "L",
  closeShort: "C",
  volumeShort: "Vol",
  up: "up",
  down: "down",
  unchanged: "unchanged",
  average: (n) => `MA ${n}`,
  zoomIn: "Zoom in",
  zoomOut: "Zoom out",
  resetZoom: "Show all",
  zoomHint: (key) => `Hold ${key} and scroll to zoom`,
  date: "Date",
  change: "Change",
  empty: "No data",
  showAll: (rows) => `Show all ${rows} rows`,
};

/**
 * Props of CandlestickChart. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type CandlestickChartProps = {
  /** One candle per period, oldest first. Candles with a missing price are skipped. */
  data: readonly Candle[];
  /** "candle" (default): bodies and wicks. "ohlc": bars with an open tick (left) and a close tick (right). */
  mode?: "candle" | "ohlc";
  /** Show the volume strip under the prices. Default: when any candle has a volume. */
  volume?: boolean;
  /** Overlay a simple moving average of the close over this many periods (e.g. 20). */
  average?: number;
  /** Sets the height of the price panel in px. Default 300. */
  height?: number;
  /** Sets the height of the volume strip in px. Default 64. */
  volumeHeight?: number;
  /**
   * Palette slots for rising and falling candles: green and red that hold >= 3:1 on the chart surface in both themes
   * (slot 6 / 8 in light, the status hues in dark). Rising candles are hollow, falling ones filled.
   *
   * @default green (rising), red (falling)
   */
  upColor?: ChartColor;
  /** Sets the palette slot (1 to 8) of falling candles. */
  downColor?: ChartColor;
  /** Sets the palette slot of the moving average. Default 1. */
  averageColor?: ChartColor;
  /** Formats a price for the axis, tooltip and data table: takes the number, returns the text shown. Default: 2 decimals in `locale`. */
  format?: (n: number) => string;
  /** Formats a volume figure as text. Default: compact in `locale`. */
  formatVolume?: (n: number) => string;
  /**
   * Formats dates (readout, table): "Thu, Oct 3, 2026" in `locale`, with the time for intraday data.
   *
   * @default "Thu, Oct 3, 2026" in locale
   */
  formatDate?: (d: Date) => string;
  /** Locale of the default number and date formats. Default "en". */
  locale?: string;
  /** IANA time zone of the default date formats, e.g. the exchange's "America/New_York". Default: the viewer's. */
  timeZone?: string;
  /** Zoom (Ctrl/⌘ + scroll, pinch, + / −) and pan (drag, Shift + arrows). Default true. */
  zoom?: boolean;
  /** Initial visible window, as candle indices [start, end). Default: every candle. */
  defaultRange?: [number, number];
  /** Called with the visible window [start, end) whenever it changes. */
  onRangeChange?: (range: [number, number]) => void;
  /** Shown when there is nothing to plot. */
  emptyState?: ReactNode;
  /** Override the chart's strings (i18n). */
  labels?: Partial<CandlestickChartLabels>;
  /** Accessible summary of what the chart shows. */
  "aria-label": string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/** One candle with its date parsed and prices in `o/h/l/c` form. @internal */
export type Parsed = {
  date: Date;
  o: number;
  h: number;
  l: number;
  c: number;
  v: number | null;
  prev: number | null;
  ma: number | null;
};

/** The fewest candles a zoom can show. @internal */
export const MIN_SPAN = 12; // fewest candles a zoom can show
/** The height of the price and date tags on the axes, in pixels. @internal */
export const PILL_H = 18; // price and date tags on the axes
/** Default rising / falling hues: >= 3:1 on the chart surface in both themes. */
export const UP = "light-dark(var(--sheen-chart-6), var(--sheen-success))";
/** The colour of a falling candle. @internal */
export const DOWN = "light-dark(var(--sheen-chart-8), var(--sheen-danger))";
/** The average glyph width used to size the axis gutters, in pixels. @internal */
export const AXIS_CH = 6.6;

/** Coerces at the data boundary: prices often arrive from JSON as numeric strings, whatever the `Candle` type says. */
export const asNumber = (value: unknown) => Number(value);

/** Valid candles with their previous close and the moving average (when asked).
 *
 * @see /charts/candlestick
 */
export function parseCandles(data: readonly Candle[], average = 0): Parsed[] {
  const out: Parsed[] = [];
  let sum = 0;
  const window: number[] = [];
  for (const d of data) {
    const o = asNumber(d.open);
    const c = asNumber(d.close);
    const hi = asNumber(d.high);
    const lo = asNumber(d.low);
    if (![o, c, hi, lo].every(Number.isFinite)) continue;
    const date = d.date instanceof Date ? d.date : new Date(d.date);
    const v = d.volume === undefined || !Number.isFinite(asNumber(d.volume)) ? null : Math.max(0, asNumber(d.volume));
    let ma: number | null = null;
    if (average > 0) {
      window.push(c);
      sum += c;
      if (window.length > average) sum -= window.shift() ?? 0;
      if (window.length === average) ma = sum / average;
    }
    out.push({
      date,
      o,
      c,
      h: Math.max(hi, lo, o, c),
      l: Math.min(hi, lo, o, c),
      v,
      prev: out[out.length - 1]?.c ?? null,
      ma,
    });
  }
  return out;
}

/** The axis and tooltip date formatters for the candle interval and time zone. @internal */
export function dateFormats(locale: string | undefined, intraday: boolean, timeZone?: string) {
  const make = (opts: Intl.DateTimeFormatOptions) => safeDateFormat(locale, { ...opts, timeZone });
  return {
    axis: make(intraday ? { hour: "2-digit", minute: "2-digit" } : { month: "short", day: "numeric" }),
    full: make(
      intraday
        ? { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }
        : { weekday: "short", month: "short", day: "numeric", year: "numeric" },
    ),
  };
}

/** The small up or down triangle of a price change. @internal */
export const Triangle = ({ down }: { down?: boolean }) => (
  <svg aria-hidden width={8} height={8} viewBox="0 0 8 8" className="shrink-0 fill-current">
    <path d={down ? "M0 1.5h8L4 7z" : "M0 6.5h8L4 1z"} />
  </svg>
);

"use client";

import { Button } from "../../button/button";
import { cn } from "../../lib/cn";
import { LegendKey } from "../chart-parts";
import { ResetIcon, ZoomIcon } from "../chart-icons";
import { Triangle, type CandlestickChartLabels, type Parsed } from "./model";

/** The line above the chart: the read (or latest) candle's date, prices, move, volume and average, and the zoom buttons. */
export function CandleReadout({
  candle,
  dateText,
  labels: t,
  widest,
  priceFormat,
  volumeFormat,
  dir,
  moveText,
  showVolume,
  average,
  maColor,
  zoomButtons,
  zoomed,
  canZoomIn,
  onZoomOut,
  onZoomIn,
  onReset,
}: {
  /** The candle being read, or the latest one. */
  candle: Parsed | undefined;
  /** Its full date, already formatted. */
  dateText: string;
  labels: CandlestickChartLabels;
  /** Characters of the widest price, so the numbers keep a fixed width. */
  widest: number;
  priceFormat: (value: number) => string;
  volumeFormat: (value: number) => string;
  dir: "up" | "down" | "flat";
  moveText: string;
  showVolume: boolean;
  average: number;
  maColor: string;
  /** Whether the zoom buttons are shown at all. */
  zoomButtons: boolean;
  zoomed: boolean;
  canZoomIn: boolean;
  onZoomOut: () => void;
  onZoomIn: () => void;
  onReset: () => void;
}) {
  return (
    <div className="flex min-h-8 flex-wrap items-center gap-x-3 gap-y-1.5 text-xs">
      <bdi aria-hidden className="text-sheen-fg-muted">
        {candle ? dateText : ""}
      </bdi>
      {candle && (
        <span aria-hidden className="flex flex-wrap items-center gap-x-2.5 gap-y-1 tabular-nums">
          {(
            [
              [t.openShort, candle.o],
              [t.highShort, candle.h],
              [t.lowShort, candle.l],
              [t.closeShort, candle.c],
            ] as const
          ).map(([k, v]) => (
            <span key={k} className="whitespace-nowrap">
              <span className="text-sheen-fg-muted">{k}</span>{" "}
              <bdi className="inline-block text-end font-semibold text-sheen-fg" style={{ minWidth: `${widest}ch` }}>
                {priceFormat(v)}
              </bdi>
            </span>
          ))}
        </span>
      )}
      {candle && (
        <span
          aria-hidden
          className={cn(
            "inline-flex items-center gap-1 rounded-sheen-full px-2 py-0.5 font-semibold whitespace-nowrap tabular-nums",
            dir === "up"
              ? "bg-sheen-success-soft text-sheen-success-text"
              : dir === "down"
                ? "bg-sheen-danger-soft text-sheen-danger-text"
                : "bg-sheen-hover text-sheen-fg-muted",
          )}
        >
          {dir !== "flat" && <Triangle down={dir === "down"} />}
          <bdi>{moveText}</bdi>
        </span>
      )}
      {showVolume && candle?.v !== null && candle?.v !== undefined && (
        <span aria-hidden className="whitespace-nowrap tabular-nums">
          <span className="text-sheen-fg-muted">{t.volumeShort}</span>{" "}
          <bdi className="font-semibold text-sheen-fg">{volumeFormat(candle.v)}</bdi>
        </span>
      )}
      {average > 0 && (
        <span aria-hidden className="inline-flex items-center gap-1.5 whitespace-nowrap tabular-nums">
          <LegendKey color={maColor} kind="line" />
          <span className="text-sheen-fg-muted">{t.average(average)}</span>
          <bdi className="font-semibold text-sheen-fg">
            {candle?.ma !== null && candle?.ma !== undefined ? priceFormat(candle.ma) : "–"}
          </bdi>
        </span>
      )}
      {zoomButtons && (
        <span className="ms-auto flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon"
            aria-label={t.zoomOut}
            disabled={!zoomed}
            className="size-8 any-pointer-coarse:size-11"
            onClick={onZoomOut}
          >
            <ZoomIcon minus />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            aria-label={t.zoomIn}
            disabled={!canZoomIn}
            className="size-8 any-pointer-coarse:size-11"
            onClick={onZoomIn}
          >
            <ZoomIcon />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            aria-label={t.resetZoom}
            disabled={!zoomed}
            className="size-8 any-pointer-coarse:size-11"
            onClick={onReset}
          >
            <ResetIcon />
          </Button>
        </span>
      )}
    </div>
  );
}

import type { ReactNode } from "react";

import { barPath } from "../chart-utils";
import type { Parsed } from "./model";

/** The geometry a candle is drawn with. @internal */
export type CandleGeometry = {
  /** `"ohlc"` draws tick bars; anything else draws candle bodies. */
  mode: string;
  step: number;
  bodyW: number;
  hollow: boolean;
  yP: (price: number) => number;
};

/** One candle (or OHLC bar): its wick and body at `cx`, in `color`. @internal */
export function candleShape(c: Parsed, cx: number, color: string, g: CandleGeometry): ReactNode {
  const { mode, step, bodyW, hollow, yP } = g;
  const isUp = c.c >= c.o;
  if (mode === "ohlc") {
    const sw = step > 6 ? 2 : 1.25;
    return (
      <>
        <line x1={cx} x2={cx} y1={yP(c.h)} y2={yP(c.l)} stroke={color} strokeWidth={sw} strokeLinecap="round" />
        <line
          x1={cx - Math.max(2, bodyW / 2)}
          x2={cx}
          y1={yP(c.o)}
          y2={yP(c.o)}
          stroke={color}
          strokeWidth={sw}
          strokeLinecap="round"
        />
        <line
          x1={cx}
          x2={cx + Math.max(2, bodyW / 2)}
          y1={yP(c.c)}
          y2={yP(c.c)}
          stroke={color}
          strokeWidth={sw}
          strokeLinecap="round"
        />
      </>
    );
  }
  const top = yP(Math.max(c.o, c.c));
  const bh = Math.max(1, yP(Math.min(c.o, c.c)) - top);
  return (
    <>
      <line x1={cx} x2={cx} y1={yP(c.h)} y2={yP(c.l)} stroke={color} strokeWidth={bodyW >= 6 ? 1.5 : 1} />
      <rect
        x={cx - bodyW / 2}
        y={top}
        width={bodyW}
        height={bh}
        rx={Math.min(2, bodyW / 4)}
        fill={isUp && hollow ? `color-mix(in oklab, ${color} 16%, var(--sheen-chart-surface))` : color}
        stroke={color}
        strokeWidth={isUp && hollow ? 1.5 : 0}
        className="forced-colors:stroke-[CanvasText]"
      />
    </>
  );
}

/** The path and fill of one volume bar at `cx`, or null when the candle has no volume. @internal */
export function volumeBarShape(
  c: Parsed,
  cx: number,
  strength: number,
  color: string,
  g: { volH: number; bodyW: number; yV: (v: number) => number },
) {
  if (c.v === null) return null;
  const h = Math.max(0, g.volH - g.yV(c.v));
  return {
    d: barPath(cx - g.bodyW / 2, g.volH - h, g.bodyW, h, "top", Math.min(3, g.bodyW / 2)),
    fill: `color-mix(in oklab, ${color} ${strength}%, transparent)`,
  };
}

"use client";

import { useMemo } from "react";

import { cn } from "../../lib/cn";
import { itemAt } from "../chart-utils";
import { ChartValueTable, defaultCompact } from "../heatmap";
import { safeNumberFormat, ShowAllRows, useTableRows } from "../category-bar";
import {
  defaultCandlestickChartLabels,
  type CandlestickChartProps,
  parseCandles,
  dateFormats,
  Triangle,
} from "./model";

/* ---------- Table view ---------- */

/**
 * Props of CandlestickTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type CandlestickTableProps = Pick<
  CandlestickChartProps,
  "data" | "format" | "formatVolume" | "formatDate" | "locale" | "timeZone" | "labels"
> & {
  /** Hidden caption that names the table for screen readers. */
  caption?: string;
  /** Sets the sort order: newest first (default), or oldest first. */
  order?: "newest" | "oldest";
  /** Rows shown before "Show all" (opening the table stays instant on long histories). Default 30. */
  limit?: number;
};

/**
 * Every candle: date, open, high, low, close, change against the previous close, and volume.
 *
 * Props: the chart's `data`, `format`, `formatVolume`, `formatDate`, `locale`, `timeZone` and `labels`, plus `caption` (hidden, names the table), `order` ("newest" first by default, or "oldest") and `limit` (rows before "Show all"). A real table: date, open, high, low, close, change and volume. Static (no motion). Pass it to `ChartCard table`.
 *
 * @example
 * ```tsx
 * import { CandlestickTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <CandlestickTable data={[{ date: "2026-03-02", open: 100, high: 108, low: 97, close: 105, volume: 1200 }]} caption="ACME share price, March" />
 *   );
 * }
 * ```
 *
 * @see /charts/candlestick
 */
export function CandlestickTable({
  data,
  format: formatProp,
  formatVolume,
  formatDate,
  locale,
  timeZone,
  labels: labelOverrides,
  caption,
  order = "newest",
  limit = 30,
}: CandlestickTableProps) {
  const t = { ...defaultCandlestickChartLabels, ...labelOverrides };
  const candles = useMemo(() => parseCandles(data), [data]);
  const nf = useMemo(() => safeNumberFormat(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 }), [locale]);
  const price = formatProp ?? ((n: number) => nf.format(n).replace("-", "−"));
  const vol = formatVolume ?? defaultCompact(locale);
  const pct = useMemo(
    () =>
      safeNumberFormat(locale, {
        style: "percent",
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
        signDisplay: "exceptZero",
      }),
    [locale],
  );
  const intraday =
    candles.length > 1 && itemAt(candles, 1).date.getTime() - itemAt(candles, 0).date.getTime() < 20 * 3_600_000;
  const dates = useMemo(() => dateFormats(locale, intraday, timeZone), [locale, intraday, timeZone]);
  const hasVolume = candles.some((c) => c.v !== null);
  const ordered = useMemo(() => (order === "newest" ? [...candles].reverse() : candles), [candles, order]);
  const { rows, hidden, showAll } = useTableRows(ordered, { cap: limit });
  const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
  return (
    <div className="flex flex-col gap-3">
      <ChartValueTable
        caption={caption}
        emptyState={t.empty}
        className="max-h-96 overflow-y-auto overscroll-contain"
        columns={[t.date, t.open, t.high, t.low, t.close, t.change, ...(hasVolume ? [t.volume] : [])].map((label) => ({
          label: cap(label),
        }))}
        rows={rows.map((c) => {
          const base = c.prev ?? c.o;
          const ratio = base !== 0 ? (c.c - base) / base : 0;
          return [
            Number.isNaN(c.date.getTime()) ? "" : formatDate ? formatDate(c.date) : dates.full.format(c.date),
            price(c.o),
            price(c.h),
            price(c.l),
            price(c.c),
            <span
              key="ch"
              className={cn(
                "inline-flex items-center gap-1",
                ratio > 0 ? "text-sheen-success-text" : ratio < 0 ? "text-sheen-danger-text" : "text-sheen-fg-muted",
              )}
            >
              {ratio !== 0 && <Triangle down={ratio < 0} />}
              {pct.format(ratio).replace("-", "−")}
            </span>,
            ...(hasVolume ? [c.v === null ? "–" : vol(c.v)] : []),
          ];
        })}
      />
      <ShowAllRows hidden={hidden} total={candles.length} label={t.showAll} onClick={showAll} />
    </div>
  );
}

"use client";

import { useEffect, type RefObject } from "react";

import { clamp } from "../chart-utils";

/** The latest view, size and actions the native listeners read, so they are bound once. @internal */
export type LiveView = {
  view: { start: number; end: number };
  innerW: number;
  count: number;
  zoom: boolean;
  left: number;
  setView: (start: number, end: number) => void;
  zoomBy: (factor: number, anchor: number) => void;
  nudgeMoving: () => void;
};

/**
 * Wheel and Safari's trackpad gestures on the chart (non-passive, so a zoom never scrolls the page).
 * Bound once the svg exists; everything else is read from `live`. A plain scroll calls `onScrollHint`.
 * @internal
 */
export function useWheelZoom(
  svgRef: RefObject<SVGSVGElement | null>,
  live: RefObject<LiveView>,
  onScrollHint: (shown: boolean) => void,
  rebind: readonly unknown[],
) {
  useEffect(() => {
    const svg = svgRef.current;
    if (!svg) return;
    let hintTimer = 0;
    const plotX = (clientX: number) => clientX - svg.getBoundingClientRect().left - live.current.left;
    const anchorAt = (clientX: number) => {
      const { view: v, innerW: w } = live.current;
      return v.start + (clamp(plotX(clientX), 0, w) / Math.max(1, w)) * (v.end - v.start);
    };
    const onWheel = (e: WheelEvent) => {
      if (!live.current.zoom || live.current.count < 2) return;
      const { view: v, innerW: w, count: n } = live.current;
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        const delta = clamp(e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY, -60, 60);
        live.current.nudgeMoving();
        live.current.zoomBy(Math.exp(delta * 0.01), anchorAt(e.clientX));
        return;
      }
      const sideways = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.shiftKey ? e.deltaY : 0;
      if (sideways !== 0) {
        if (v.end - v.start >= n - 0.01) return;
        e.preventDefault();
        const di = (sideways / Math.max(1, w)) * (v.end - v.start);
        live.current.nudgeMoving();
        live.current.setView(v.start + di, v.end + di);
        return;
      }
      // A plain scroll keeps scrolling the page; say how to zoom instead.
      onScrollHint(true);
      window.clearTimeout(hintTimer);
      hintTimer = window.setTimeout(() => onScrollHint(false), 1400);
    };
    type GestureLike = Event & { scale: number; clientX: number };
    let gestureStart: { span: number; scale: number } | null = null;
    const onGestureStart = (e: Event) => {
      if (!live.current.zoom) return;
      e.preventDefault();
      const v = live.current.view;
      gestureStart = { span: v.end - v.start, scale: (e as GestureLike).scale || 1 };
    };
    const onGestureChange = (e: Event) => {
      if (!gestureStart || !live.current.zoom) return;
      e.preventDefault();
      const g = e as GestureLike;
      const v = live.current.view;
      const nextSpan = gestureStart.span / Math.max(0.05, g.scale / gestureStart.scale);
      live.current.nudgeMoving();
      live.current.zoomBy(nextSpan / (v.end - v.start), anchorAt(g.clientX));
    };
    const onGestureEnd = () => (gestureStart = null);
    svg.addEventListener("wheel", onWheel, { passive: false });
    svg.addEventListener("gesturestart", onGestureStart);
    svg.addEventListener("gesturechange", onGestureChange);
    svg.addEventListener("gestureend", onGestureEnd);
    return () => {
      window.clearTimeout(hintTimer);
      svg.removeEventListener("wheel", onWheel);
      svg.removeEventListener("gesturestart", onGestureStart);
      svg.removeEventListener("gesturechange", onGestureChange);
      svg.removeEventListener("gestureend", onGestureEnd);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- bound again only when the svg appears or disappears
  }, rebind);
}

